from pydantic_ai.profiles.openai import OpenAIJsonSchemaTransformer
from app.review.verdict import *
import app.review.verdict as v, inspect
from pydantic import BaseModel
bad=[]
def walk(n,path):
    if isinstance(n,dict):
        if n.get("type")=="object" or "properties" in n:
            if n.get("additionalProperties") is not False: bad.append((path,"addl"))
            if set(n.get("properties",{}))!=set(n.get("required",[])): bad.append((path,"req"))
        for k,x in n.items():
            if k in("allOf","not","if","then","else"): bad.append((path,k))
            walk(x,path+"/"+k)
    elif isinstance(n,list):
        for i,x in enumerate(n): walk(x,path)
for name,c in inspect.getmembers(v,inspect.isclass):
    if issubclass(c,BaseModel) and c.__module__==v.__name__:
        t=OpenAIJsonSchemaTransformer(c.model_json_schema(),strict=True).walk()
        before=len(bad); walk(t,name); print(name,"issues",len(bad)-before, t.get("type"), "anyOf" in t)
print(bad[:5])
EOF
PYTHONPATH=. .venv/Scripts/python.exe "$TEMP/chk.py"

