"""pre-commit hook: only allow-listed paths may be committed; lint and quick tests run when the tools exist."""
import fnmatch
import hashlib
import re
import subprocess
import sys
from pathlib import Path

ALLOWED_DIRS = ("app/", "tests/", "frontend/", "config/", "docs/", ".github/", "output/", "transcripts/")
ALLOWED_FILES = {
    "run.py", "README.md", "DECISIONS.md", "VALIDATION.md", "REFLECTION.md",
    "pyproject.toml", ".gitignore", ".env.example", ".gitattributes",
}
MARKER_DIRS = ("ledger/", "output/", "transcripts/")
MARKER_FILES = {".gitkeep", "README.md"}
ALWAYS_REJECT_DIRS = (".agent/", ".claude/", ".venv/", ".northwind/")
ALWAYS_REJECT_PATTERNS = ("CLAUDE*.md", ".env", "*.pyc", "*.db", "*.log")
MAX_BYTES = 1_000_000
KEY_PATTERN = re.compile(
    r"sk-[A-Za-z0-9_\-]{20,}|AIza[0-9A-Za-z_\-]{35}|Bearer\s+[A-Za-z0-9._\-]{20,}"
    r"|(?:OPENAI|GOOGLE|ANTHROPIC)_API_KEY\s*=\s*[\"']?[A-Za-z0-9_\-]{8,}"
)
BRIEF = "Northwind_TakeHome_v2/"


def git(*args: str) -> subprocess.CompletedProcess:
    return subprocess.run(["git", *args], capture_output=True, text=True)


def staged() -> list[str]:
    out = git("diff", "--cached", "--name-only", "--diff-filter=ACMR", "-z").stdout
    return [p for p in out.split("\0") if p]


def is_first_commit() -> bool:
    return git("rev-parse", "--verify", "-q", "HEAD").returncode != 0


def recorded_hashes() -> dict[str, str]:
    """Manifest as committed in HEAD, so a staged edit to the manifest cannot approve itself."""
    text = git("show", "HEAD:config/bundle_manifest.sha256").stdout
    return {name: digest for digest, name in (line.split(None, 1) for line in text.splitlines() if line.strip())}


def bundle_problem(path: str) -> str | None:
    """After the first commit a bundle file may only be re-stored byte for byte as recorded."""
    name = path[len(BRIEF):].removeprefix("data/")
    expected = recorded_hashes().get(name)
    if not path.startswith(BRIEF + "data/") or expected is None:
        return "only data files listed in config/bundle_manifest.sha256 may be touched"
    blob = subprocess.run(["git", "show", f":{path}"], capture_output=True).stdout
    if hashlib.sha256(blob).hexdigest() != expected:
        return "staged bytes differ from config/bundle_manifest.sha256"
    return None


def deleted_bundle_files() -> list[str]:
    out = git("diff", "--cached", "--name-only", "--diff-filter=D", "-z").stdout
    return [p for p in out.split("\0") if p.startswith(BRIEF)]


def problem(path: str, first_commit: bool) -> str | None:
    name = path.rsplit("/", 1)[-1]
    if path.startswith(ALWAYS_REJECT_DIRS) or "__pycache__/" in path:
        return "local-only folder or cache"
    if any(fnmatch.fnmatch(name, pat) for pat in ALWAYS_REJECT_PATTERNS):
        return "never committed (secret, cache, database or log)"
    if path.startswith(BRIEF):
        return None if first_commit else bundle_problem(path)
    if path.startswith("docs/") and not path.endswith((".md", ".png", ".svg", ".jpg")):
        return "docs/ holds markdown and diagram images only"
    if path.startswith(MARKER_DIRS) and name not in MARKER_FILES:
        if not (path.startswith("ledger/") and name.endswith(".jsonl")):
            return "ledger/, output/ and transcripts/ hold only .gitkeep and README.md (ledger/ also .jsonl)"
    if path.startswith("ledger/") or path.startswith(ALLOWED_DIRS) or path in ALLOWED_FILES:
        return None
    if fnmatch.fnmatch(path, "requirements*.txt"):
        return None
    return "not on the allow-list"


def secret_problem(path: str) -> str | None:
    """Staged text that looks like an API key. A line marked FAKE (a test value) is allowed."""
    if path.startswith(BRIEF):
        return None
    blob = subprocess.run(["git", "show", f":{path}"], capture_output=True).stdout.decode("utf-8", "ignore")
    for line in blob.splitlines():
        if KEY_PATTERN.search(line) and "FAKE" not in line:
            return "looks like an API key (mark a test value with FAKE)"
    return None


def too_big(path: str) -> bool:
    if path.startswith(BRIEF):
        return False
    file = Path(path)
    return file.is_file() and file.stat().st_size > MAX_BYTES


def tool_python() -> str:
    """The project's own interpreter when .venv exists: the one on PATH in a git hook may lack the tools."""
    for rel in (".venv/Scripts/python.exe", ".venv/bin/python"):
        if Path(rel).is_file():
            return str(Path(rel).resolve())
    return sys.executable


def installed(python: str, module: str) -> bool:
    probe = f"import importlib.util, sys; sys.exit(importlib.util.find_spec({module!r}) is None)"
    return subprocess.run([python, "-c", probe]).returncode == 0


def run_checks(paths: list[str]) -> int:
    """Lint, type check and test with whatever is installed; a missing tool is said out loud, never skipped quietly."""
    python = tool_python()
    py = [p for p in paths if p.endswith(".py")]
    steps = [("ruff", ["check", *py]), ("mypy", ["app"]), ("pytest", ["-q", "-x", "tests"])]
    for module, args in steps:
        if module != "pytest" and not py:
            continue
        if module == "pytest" and not Path("tests").is_dir():
            continue
        if not installed(python, module):
            print(f"pre-commit: {module} is not installed, check skipped", file=sys.stderr)
            continue
        if subprocess.run([python, "-m", module, *args]).returncode:
            return 1
    return 0


def main() -> int:
    paths = staged()
    first = is_first_commit()
    bad = [(p, why) for p in paths if (why := problem(p, first))]
    bad += [(p, "larger than 1 MB") for p in paths if too_big(p)]
    bad += [(p, why) for p in paths if (why := secret_problem(p))]
    if not first:
        bad += [(p, "supplied files are never deleted") for p in deleted_bundle_files()]
    if bad:
        for path, why in bad:
            print(f"pre-commit rejected {path}: {why}", file=sys.stderr)
        return 1
    return run_checks(paths)


if __name__ == "__main__":
    sys.exit(main())

